{
  "aggregate_id": "DEF-NRS-484B-017::electric_bicycle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "underdetermined",
      "reason": "The opening alternative can admit unassisted two- or three-wheeled members outside ru.electric_bicycle, defeating complete coverage, while the bicycle contract does not itself establish the required wheel count."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The opening alternative admits rideable two- or three-wheeled devices, and the many-passenger motor-vehicle contract neither establishes nor rules out that configuration."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The admitting words describe a device, whereas this contract describes a child pedestrian."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial mass or licensing does not establish or preclude the rideable two- or three-wheeled configuration admitted by the opening alternative."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "underdetermined",
      "reason": "An assisting electric motor alone establishes neither the opening alternative's wheel count nor the separate bicycle alternative's equipment, power and operating requirements."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The definition expressly states that the term does not include an electric scooter."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Emergency designation does not determine wheel count or prevent a device from satisfying the opening admitting alternative."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "A fire-fighting purpose neither establishes nor rules out a rideable two- or three-wheeled device, which the opening alternative admits."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The definition expressly states that the term does not include a moped."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract does not settle whether a member satisfies the opening two-or-three-wheel alternative, and excluding separately classified powered two-wheelers does not rule out qualifying three-wheelers."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "contradicted",
      "reason": "The opening alternative directly admits rideable devices having two or three wheels, which the motorcycle contract describes, without restricting that alternative to pedalled bicycles."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official or contracted road service neither establishes nor precludes the rideable two- or three-wheeled configuration admitted by the opening alternative."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The admitting words describe a device rather than the person described by the pedestrian contract."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The opening words admit devices, not pedestrians carrying a cane or accompanied or led by another."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The target definition does not exclude on-track devices, and the rail-vehicle contract does not settle whether they satisfy its rideability and wheel-count requirements."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-bus designation and markings do not establish or rule out the configuration admitted by the opening two-or-three-wheel alternative."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "Passenger-for-hire use and markings do not determine whether the vehicle meets the opening rideable two-or-three-wheel alternative."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The contract's service, body and livery descriptions do not settle the wheel-count requirement, and the opening alternative is not limited to pedalled bicycles."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "Being drawn by another vehicle neither establishes nor precludes rideability with two or three wheels, and the target definition contains no drawn-vehicle exclusion."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service and identifying displays do not establish or rule out the rideable two-or-three-wheel configuration admitted by the opening alternative."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not settle wheel count or preclude the opening admitting alternative, so the quoted bicycle-specific limb does not establish exclusion."
    }
  ]
}

